1	/// Escape a scalar value for TOON row output.
2	///
3	/// Values containing commas, double-quotes, or newlines are wrapped in
4	/// double-quotes with internal double-quotes escaped as `\"`. Empty values
5	/// are returned as-is (the comma delimiter is still emitted by the caller).
6	pub(crate) fn escape_value(v: &str) -> std::borrow::Cow<'_, str> {
7	    if v.is_empty() {
8	        return std::borrow::Cow::Borrowed(v);
9	    }
10	    if v.contains(',') || v.contains('"') || v.contains('\n') || v.contains('\r') {
11	        let mut out = String::with_capacity(v.len() * 2 + 2);
12	        out.push('"');
13	        for ch in v.chars() {
14	            if ch == '"' {
15	                out.push('\\');
16	            }
17	            out.push(ch);
18	        }
19	        out.push('"');
20	        std::borrow::Cow::Owned(out)
21	    } else {
22	        std::borrow::Cow::Borrowed(v)
23	    }
24	}
25	
