3	/// A single cell value in a TOON row.
4	#[derive(Debug, Clone, PartialEq)]
5	pub enum Value {
6	    /// UTF-8 string. Escaped if it contains commas, quotes, carriage returns, or newlines.
7	    Str(String),
8	    /// Signed integer.
9	    Int(i64),
10	    /// Floating-point number.
11	    Float(f64),
12	    /// Boolean renders as `true` or `false`.
13	    Bool(bool),
14	    /// Null renders as empty string (delimiter still emitted by the caller).
15	    Null,
16	}
17	
18	/// Render a TOON document string from its parts.
19	///
20	/// Pre-allocates output capacity based on row count × estimated row width.
21	pub(crate) fn render(
22	    type_name: &str,
23	    fields: &[String],
24	    rows: &[Vec<Value>],
25	    total_count: Option<usize>,
26	    hints: &[String],
27	) -> String {
28	    let row_count = rows.len();
29	    let field_count = fields.len();
30	    let capacity = 60 + row_count * (field_count * 12 + 10) + hints.len() * 60;
31	    let mut out = String::with_capacity(capacity);
32	
33	    // type_name[count]{field,field,...}:
34	    out.push_str(type_name);
35	    out.push('[');
36	    out.push_str(&row_count.to_string());
37	    out.push_str("]{");
38	    for (i, field) in fields.iter().enumerate() {
39	        if i > 0 {
40	            out.push(',');
41	        }
42	        out.push_str(field);
43	    }
44	    out.push_str("}:\n");
45	
46	    // rows
47	    for row in rows {
48	        out.push_str("  ");
49	        for (i, val) in row.iter().enumerate() {
50	            if i > 0 {
51	                out.push(',');
52	            }
53	            let s = match val {
54	                Value::Str(s) => escape_value(s),
55	                Value::Int(n) => std::borrow::Cow::Owned(n.to_string()),
56	                Value::Float(f) => std::borrow::Cow::Owned(f.to_string()),
57	                Value::Bool(b) => std::borrow::Cow::Borrowed(if *b { "true" } else { "false" }),
58	                Value::Null => std::borrow::Cow::Borrowed(""),
59	            };
60	            out.push_str(&s);
61	        }
62	        out.push('\n');
63	    }
64	
65	    // totalCount
66	    if let Some(total) = total_count {
67	        out.push_str("totalCount: ");
68	        out.push_str(&total.to_string());
69	        out.push('\n');
70	    }
71	
72	    // help[N]: hints
73	    if !hints.is_empty() {
74	        out.push_str("help[");
75	        out.push_str(&hints.len().to_string());
76	        out.push_str("]:\n");
77	        for hint in hints {
78	            out.push_str("  ");
79	            out.push_str(hint);
80	            out.push('\n');
81	        }
82	    }
83	
84	    out
85	}
