10	/// A value in a key-value item.
11	#[derive(Debug, Clone, PartialEq)]
12	pub enum KvValue {
13	    /// UTF-8 string value.
14	    Str(String),
15	    /// Signed integer.
16	    Int(i64),
17	    /// Floating-point number.
18	    Float(f64),
19	    /// Boolean renders as `true` or `false`.
20	    Bool(bool),
21	    /// Null renders as empty string after the colon.
22	    Null,
23	}
