25	/// Render a list of key-value pairs as a multi-line `key: value` block.
26	///
27	/// Preferred for single items and small metadata blocks (up to ~5 fields).
28	/// For lists of 5+ items, prefer [`crate::toon::render_toon`].
29	///
30	/// Returns an empty string when `items` is empty.
31	#[must_use]
32	pub fn render_kv(items: &[KvItem]) -> String {
33	    if items.is_empty() {
34	        return String::new();
35	    }
36	    let capacity = items.len() * 20;
37	    let mut out = String::with_capacity(capacity);
38	    for item in items {
39	        out.push_str(&item.key);
40	        out.push_str(": ");
41	        match &item.value {
42	            KvValue::Str(s) => out.push_str(s),
43	            KvValue::Int(n) => out.push_str(&n.to_string()),
44	            KvValue::Float(f) => out.push_str(&f.to_string()),
45	            KvValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
46	            KvValue::Null => {}
47	        }
48	        out.push('\n');
49	    }
50	    out
51	}
