55	/// A collection of status items with an overall health summary.
56	#[derive(Debug, Clone, PartialEq)]
57	pub struct StatusResponse {
58	    /// Aggregate health across all items.
59	    pub overall: Health,
60	    /// Individual component statuses.
61	    pub items: Vec<StatusItem>,
62	    /// Optional contextual hints for the agent.
63	    pub hints: Vec<Hint>,
64	}
65	
66	impl StatusResponse {
67	    /// Create a status response. `overall` is the caller-supplied aggregate — michi
68	    /// does not recompute it from `items` so the caller controls the roll-up logic.
69	    pub fn new(overall: Health, items: Vec<StatusItem>) -> Self {
70	        Self { overall, items, hints: Vec::new() }
71	    }
72	
73	    /// Attach contextual hints.
74	    pub fn with_hints(mut self, hints: Vec<Hint>) -> Self {
75	        self.hints = hints;
76	        self
77	    }
78	
79	    /// Render this status response as an agent-readable string.
80	    ///
81	    /// Format:
82	    /// ```text
83	    /// status: ok
84	    /// db: ok
85	    /// cache: degraded (high latency)
86	    /// queue: down
87	    /// help[1]:
88	    ///   check queue logs
89	    /// ```
90	    #[must_use]
91	    pub fn render(&self) -> String {
92	        let mut capacity = 16 + self.items.len() * 32;
93	        if !self.hints.is_empty() {
94	            capacity += 8 + self.hints.len() * 40;
95	        }
96	        let mut out = String::with_capacity(capacity);
97	        out.push_str("status: ");
98	        out.push_str(self.overall.label());
99	        out.push('\n');
100	        for item in &self.items {
101	            out.push_str(&item.name);
102	            out.push_str(": ");
103	            out.push_str(item.health.label());
104	            if let Some(detail) = &item.detail {
105	                out.push_str(" (");
106	                out.push_str(detail);
107	                out.push(')');
108	            }
109	            out.push('\n');
110	        }
111	        crate::hints::append_hints(&mut out, &self.hints);
112	        out
113	    }
114	}
