4	/// Classification of a `michi::Error` for routing and display decisions.
5	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
6	pub enum ErrorClass {
7	    /// The caller provided invalid input. Do not retry.
8	    User,
9	    /// An internal or infrastructure failure. May be retryable.
10	    Internal,
11	    /// A transient failure expected to resolve without intervention.
12	    Transient,
13	}
