15	/// Wraps a value so its inner content is omitted from `Debug` and `Display`.
16	///
17	/// Use this to prevent secrets (tokens, keys, passwords) from appearing in
18	/// logs or error messages.
19	#[derive(Clone)]
20	pub struct Sensitive<T>(pub T);
21	
22	impl<T> std::fmt::Debug for Sensitive<T> {
