34	/// The unified error type for the michi crate.
35	///
36	/// Carries both agent-renderable information (via [`Error::render`]) and
37	/// machine-readable classification (via [`Error::class`]).
38	///
39	/// Execution-layer variants (`Http`, `Timeout`, etc.) are only present when
40	/// the `pipeline` feature is enabled.
41	#[derive(Debug, thiserror::Error)]
42	pub enum Error {
43	    // ── Domain errors (always compiled) ───────────────────────────────────
44	    /// The caller provided invalid or malformed input.
45	    #[error("Invalid input: {0}")]
46	    InvalidInput(String),
47	
48	    /// A required resource was not found.
49	    #[error("Not found: {0}")]
50	    NotFound(String),
51	
52	    // ── Execution errors (pipeline feature — Plan 2) ───────────────────────
53	    /// An HTTP request returned a non-success status code.
54	    #[cfg(feature = "pipeline")]
55	    #[error("HTTP {status}: {message}")]
56	    Http {
57	        /// HTTP status code.
58	        status: u16,
59	        /// Error message from the response body.
60	        message: String,
61	        /// Whether this error is safe to retry.
62	        retryable: bool,
63	        /// Parsed `Retry-After` delay, if present.
64	        retry_after: Option<Duration>,
65	    },
66	
67	    /// An operation exceeded its allotted time budget.
68	    #[cfg(feature = "pipeline")]
69	    #[error("Timeout after {elapsed:?}")]
70	    Timeout {
71	        /// How long the operation ran before timing out.
72	        elapsed: Duration,
73	    },
74	
75	    /// A pipeline step failed during execution.
76	    #[cfg(feature = "pipeline")]
77	    #[error("Step {id} failed")]
78	    StepFailed {
79	        /// Step identifier.
80	        id: String,
81	        /// Underlying cause.
82	        #[source]
83	        source: Box<Self>,
84	    },
85	
86	    /// A circuit breaker is open and rejecting calls.
87	    #[cfg(feature = "pipeline")]
88	    #[error("Circuit {name} is open, retry after {retry_after:?}")]
89	    CircuitOpen {
90	        /// Circuit breaker name.
91	        name: String,
92	        /// When the circuit is expected to allow retries.
93	        retry_after: Duration,
94	    },
95	
96	    /// A fuzzy-match query produced no candidates.
97	    #[cfg(feature = "pipeline")]
98	    #[error("No match for query: {query}")]
99	    NoMatch {
100	        /// The query that produced no matches.
101	        query: String,
102	    },
103	
104	    /// A fuzzy-match query produced multiple equally-likely candidates.
105	    #[cfg(feature = "pipeline")]
106	    #[error("Ambiguous match for '{query}': {count} candidates")]
107	    AmbiguousMatch {
108	        /// The query that produced multiple matches.
109	        query: String,
110	        /// Number of candidates found.
111	        count: usize,
112	    },
113	
114	    /// A pipeline's step dependencies form a cycle.
115	    #[cfg(feature = "pipeline")]
116	    #[error("Cyclic dependency detected: {cycle:?}")]
117	    CyclicDependency {
118	        /// The cycle path, as a list of step IDs.
119	        cycle: Vec<String>,
120	    },
121	
122	    /// The operation was cancelled before completion.
123	    #[cfg(feature = "pipeline")]
124	    #[error("Operation was cancelled")]
125	    Cancelled,
126	
127	    /// The cache backend encountered an error.
128	    #[cfg(feature = "pipeline")]
129	    #[error("Cache error: {0}")]
130	    Cache(String),
131	
132	    /// An underlying I/O operation failed.
133	    #[cfg(feature = "pipeline")]
134	    #[error(transparent)]
135	    Io(#[from] std::io::Error),
136	}
137	
138	impl Error {
139	    /// Render this error as an agent-readable plain-text string.
140	    ///
141	    /// The output is suitable for writing to stdout before exiting with
142	    /// [`Error::exit_code`].
143	    #[must_use]
144	    pub fn render(&self) -> String {
145	        format!("error: {self}")
146	    }
147	
148	    /// The process exit code to use when this error is fatal.
149	    #[must_use]
150	    pub fn exit_code(&self) -> i32 {
151	        1
152	    }
153	
154	    /// Classify this error for routing decisions (retry, alert, display).
155	    #[must_use]
156	    pub fn class(&self) -> ErrorClass {
157	        match self {
158	            Self::InvalidInput(_) | Self::NotFound(_) => ErrorClass::User,
159	            #[cfg(feature = "pipeline")]
160	            Self::Http { retryable: true, .. } | Self::Timeout { .. } | Self::Cancelled => ErrorClass::Transient,
161	            #[cfg(feature = "pipeline")]
162	            Self::Http { retryable: false, .. }
163	            | Self::StepFailed { .. }
164	            | Self::CircuitOpen { .. }
165	            | Self::NoMatch { .. }
166	            | Self::AmbiguousMatch { .. }
167	            | Self::CyclicDependency { .. }
168	            | Self::Cache(_)
169	            | Self::Io(_) => ErrorClass::Internal,
170	        }
171	    }
172	
173	    /// Whether this error is safe to retry automatically.
174	    #[must_use]
175	    pub fn is_retryable(&self) -> bool {
176	        matches!(self.class(), ErrorClass::Transient)
177	    }
178	}
179	
