1	/// Result of a truncation operation.
2	#[derive(Debug, Clone, PartialEq)]
3	pub struct Truncated {
4	    /// The truncated (or original) content string.
5	    pub content: String,
6	    /// Original byte length of the input.
7	    pub original_len: usize,
8	    /// Whether truncation actually occurred.
9	    pub was_truncated: bool,
10	}
11	
12	/// Truncate `content` to at most `max_chars` Unicode scalar values, appending
13	/// an agent-readable suffix when truncation occurs.
14	///
15	/// The suffix pattern is `" ({n} chars truncated — use {hint})"`. Uses char
16	/// boundaries — never splits a Unicode scalar.
17	///
18	/// Returns the original string unchanged when `content.chars().count() <= max_chars`.
19	#[must_use]
20	pub fn truncate(content: &str, max_chars: usize, hint: &str) -> Truncated {
21	    let char_count = content.chars().count();
22	    if char_count <= max_chars {
23	        return Truncated { content: content.to_string(), original_len: content.len(), was_truncated: false };
24	    }
25	
26	    let suffix = format!(" ({char_count} chars truncated — use {hint})");
27	    let suffix_chars = suffix.chars().count();
28	    let keep_chars = max_chars.saturating_sub(suffix_chars);
29	
30	    let byte_end = content.char_indices().nth(keep_chars).map_or(content.len(), |(i, _)| i);
31	
32	    let mut result = String::with_capacity(byte_end + suffix.len());
33	    result.push_str(&content[..byte_end]);
34	    result.push_str(&suffix);
35	
36	    // Hard-cap to max_chars via char boundaries in case the suffix alone
37	    // exceeds max_chars (e.g. very small max_chars or long hint string).
38	    if result.chars().count() > max_chars {
39	        let cap_byte = result.char_indices().nth(max_chars).map_or(result.len(), |(i, _)| i);
40	        result.truncate(cap_byte);
41	    }
42	
43	    Truncated { content: result, original_len: content.len(), was_truncated: true }
44	}
45	
46	/// Truncate content for inline use (e.g. inside a TOON field).
47	///
48	/// Returns the final string directly.
49	#[must_use]
50	pub fn truncate_inline(content: &str, max_chars: usize, hint: &str) -> String {
51	    truncate(content, max_chars, hint).content
52	}
53	
54	#[cfg(test)]
