1	/// A contextual usage hint for an agent.
2	///
3	/// Hints are surfaced in `help[N]:` blocks at the end of TOON or kv responses.
4	/// They teach the agent what to call next.
5	#[derive(Debug, Clone, PartialEq)]
6	pub struct Hint(pub String);
7	
8	impl Hint {
9	    /// Create a hint from any string-like value.
10	    pub fn new(s: impl Into<String>) -> Self {
11	        Self(s.into())
12	    }
13	
14	    /// The raw hint string.
15	    pub fn as_str(&self) -> &str {
16	        &self.0
17	    }
18	}
