32	/// Render a `help[N]:` block from a slice of hints.
33	///
34	/// Returns an empty string when `hints` is empty.
35	#[must_use]
36	pub fn render_hints(hints: &[Hint]) -> String {
37	    if hints.is_empty() {
38	        return String::new();
39	    }
40	    let capacity = 12 + hints.len() * 50;
41	    let mut out = String::with_capacity(capacity);
42	    out.push_str("help[");
43	    out.push_str(&hints.len().to_string());
44	    out.push_str("]:\n");
45	    for hint in hints {
46	        out.push_str("  ");
47	        out.push_str(hint.as_str());
48	        out.push('\n');
49	    }
50	    out
51	}
