4	/// The serialisation format for `AgentResponse::render`.
5	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
6	pub enum OutputFormat {
7	    /// Plain-text TOON / kv / status format. Default.
8	    #[default]
9	    Text,
10	    /// Compact JSON object — field names match the builder setters.
11	    Json,
12	}
13	
14	/// Builder for composing a complete agent response from michi primitives.
15	///
16	/// An `AgentResponse` collects a primary content body, optional recovery hints,
17	/// optional contextual hints, and metadata, then renders the whole thing as a
18	/// single string via [`AgentResponse::render`].
19	///
20	/// # Examples
21	///
22	/// ```rust
23	/// use michi::response::{AgentResponse, OutputFormat};
24	/// use michi::hints::Hint;
25	///
26	/// let out = AgentResponse::new("issue[0]{}:\ntotalCount: 0\n")
27	///     .with_hint(Hint::new("Try a broader filter"))
28	///     .render(OutputFormat::Text);
29	/// assert!(out.contains("help[1]:"));
30	/// ```
31	#[derive(Debug, Clone)]
32	pub struct AgentResponse {
33	    /// Primary content body (TOON block, kv block, status block, etc.).
34	    pub body: String,
35	    /// Contextual hints appended after `body`.
36	    pub hints: Vec<Hint>,
37	    /// Structured recovery hints appended after `hints`.
38	    pub recovery: Vec<RecoveryHint>,
39	    /// Whether the response represents an error state.
40	    pub is_error: bool,
41	}
42	
43	impl AgentResponse {
44	    /// Create a new response with the given body. Hints and recovery are empty.
45	    pub fn new(body: impl Into<String>) -> Self {
46	        Self { body: body.into(), hints: Vec::new(), recovery: Vec::new(), is_error: false }
47	    }
48	
49	    /// Create a new response that represents an error state.
50	    pub fn error(body: impl Into<String>) -> Self {
51	        Self { body: body.into(), hints: Vec::new(), recovery: Vec::new(), is_error: true }
52	    }
53	
54	    /// Append a contextual hint.
55	    pub fn with_hint(mut self, hint: impl Into<Hint>) -> Self {
56	        self.hints.push(hint.into());
57	        self
58	    }
59	
60	    /// Replace all contextual hints.
61	    pub fn with_hints(mut self, hints: Vec<Hint>) -> Self {
62	        self.hints = hints;
63	        self
64	    }
65	
66	    /// Append a recovery hint.
67	    pub fn with_recovery(mut self, hint: RecoveryHint) -> Self {
68	        self.recovery.push(hint);
69	        self
70	    }
71	
72	    /// Replace all recovery hints.
73	    pub fn with_recoveries(mut self, hints: Vec<RecoveryHint>) -> Self {
74	        self.recovery = hints;
75	        self
76	    }
77	
78	    /// Mark this response as an error state.
79	    pub fn as_error(mut self) -> Self {
80	        self.is_error = true;
81	        self
82	    }
83	
84	    /// Render the response in the requested format.
85	    ///
86	    /// **Text format:** `body` + optional `help[N]:` block + optional `recovery[N]:` block.
87	    ///
88	    /// **Json format:** `{"body":"...","hints":[...],"recovery":[{"action":"...","description":"...","example":"..."}],"isError":false}`
89	    #[must_use]
90	    pub fn render(&self, format: OutputFormat) -> String {
91	        match format {
92	            OutputFormat::Text => self.render_text(),
93	            OutputFormat::Json => self.render_json(),
94	        }
95	    }
96	
97	    fn render_text(&self) -> String {
98	        let hint_block = crate::hints::render_hints(&self.hints);
99	        let recovery_block = crate::recovery::render_recovery(&self.recovery);
100	        let capacity = self.body.len() + hint_block.len() + recovery_block.len();
101	        let mut out = String::with_capacity(capacity);
102	        out.push_str(&self.body);
103	        out.push_str(&hint_block);
104	        out.push_str(&recovery_block);
105	        out
106	    }
107	
108	    fn render_json(&self) -> String {
109	        // Hand-built JSON — no serde dep in default features.
110	        let mut out = String::with_capacity(128);
111	        out.push_str("{\"body\":");
112	        json_string(&mut out, &self.body);
113	        out.push_str(",\"hints\":[");
114	        for (i, h) in self.hints.iter().enumerate() {
115	            if i > 0 {
116	                out.push(',');
117	            }
118	            json_string(&mut out, h.as_str());
119	        }
120	        out.push_str("],\"recovery\":[");
121	        for (i, r) in self.recovery.iter().enumerate() {
122	            if i > 0 {
123	                out.push(',');
124	            }
125	            out.push_str("{\"action\":");
126	            json_string(&mut out, &r.action);
127	            out.push_str(",\"description\":");
128	            json_string(&mut out, &r.description);
129	            if let Some(ex) = &r.example {
130	                out.push_str(",\"example\":");
131	                json_string(&mut out, ex);
132	            }
133	            out.push('}');
134	        }
135	        out.push_str("],\"isError\":");
136	        out.push_str(if self.is_error { "true" } else { "false" });
137	        out.push('}');
138	        out
139	    }
140	}
141	
142	/// Append a JSON-encoded string (with surrounding quotes and escape sequences)
143	/// to `out`. Escapes `"`, `\`, `\n`, `\r`, `\t`.
144	fn json_string(out: &mut String, s: &str) {
145	    out.push('"');
146	    for ch in s.chars() {
147	        match ch {
148	            '"' => out.push_str("\\\""),
149	            '\\' => out.push_str("\\\\"),
150	            '\n' => out.push_str("\\n"),
151	            '\r' => out.push_str("\\r"),
152	            '\t' => out.push_str("\\t"),
153	            other => out.push(other),
154	        }
155	    }
156	    out.push('"');
157	}
