1	/// Circuit breaker state machine (requires the `pipeline` feature).
2	#[cfg(feature = "pipeline")]
3	pub mod circuit;
4	/// Retry and back-off policy execution (requires the `pipeline` feature).
5	#[cfg(feature = "pipeline")]
6	pub mod policy;
7	
8	use std::time::Duration;
9	
10	/// Configuration for automatic retry behaviour.
11	///
12	/// Callers implement the retry loop; michi provides the delay computation via
13	/// [`next_retry_delay`]. This keeps the crate sync and runtime-agnostic.
14	#[derive(Debug, Clone)]
15	pub struct RetryConfig {
16	    /// Maximum number of retry attempts (not counting the initial attempt).
17	    pub max_retries: u32,
18	    /// Base delay for exponential back-off.
19	    pub base_delay: Duration,
20	    /// Maximum delay cap — back-off never exceeds this.
21	    pub max_delay: Duration,
22	    /// Jitter factor in `[0.0, 1.0]`. `0.0` = no jitter, `1.0` = full jitter.
23	    pub jitter_factor: f64,
24	}
25	
26	// Manually implemented because the defaults are meaningful non-zero values
27	// that `#[derive(Default)]` cannot express (it would set all durations to zero).
28	impl Default for RetryConfig {
29	    fn default() -> Self {
30	        Self {
31	            max_retries: 3,
32	            base_delay: Duration::from_millis(500),
33	            max_delay: Duration::from_secs(30),
34	            jitter_factor: 0.2,
35	        }
36	    }
37	}
38	
39	/// Compute the delay before the next retry attempt.
40	///
41	/// Uses exponential back-off: `base_delay * 2^attempt`, capped at
42	/// `max_delay`, with optional jitter derived from `jitter_seed` (a value in
43	/// `[0.0, 1.0]` supplied by the caller — use a PRNG, not `rand` inside michi).
44	///
45	/// Returns `None` when `attempt >= config.max_retries`.
46	#[must_use]
47	// Casts are safe: delays are capped at max_delay (≤ 30 s by default, well within u64 ms range).
48	// jitter_seed is documented as [0.0, 1.0], so the f64 product is non-negative and bounded.
49	#[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss, clippy::cast_sign_loss)]
50	pub fn next_retry_delay(config: &RetryConfig, attempt: u32, jitter_seed: f64) -> Option<Duration> {
51	    if attempt >= config.max_retries {
52	        return None;
53	    }
54	    let exp = 2u64.saturating_pow(attempt);
55	    let base_ms = config.base_delay.as_millis() as u64;
56	    let raw_ms = base_ms.saturating_mul(exp);
57	    let capped_ms = raw_ms.min(config.max_delay.as_millis() as u64);
58	    let jitter_ms = (capped_ms as f64 * config.jitter_factor * jitter_seed) as u64;
59	    Some(Duration::from_millis(capped_ms + jitter_ms))
60	}
61	
62	/// Parse the value of an HTTP `Retry-After` header as a delay in seconds.
63	///
64	/// Handles delay-seconds (integer) format. HTTP-date format is not parsed
65	/// (would require a date library dep) — returns `None` for dates.
66	/// Callers that need date parsing convert to seconds themselves.
67	#[must_use]
68	pub fn parse_retry_after(header_value: &str) -> Option<Duration> {
69	    header_value.trim().parse::<u64>().ok().map(Duration::from_secs)
70	}
71	
72	/// Return `true` if the HTTP status code is conventionally retryable.
73	///
74	/// Retryable status codes: 429 (rate limit), 500, 502, 503, 504.
75	#[must_use]
76	pub fn is_retryable_status(status: u16) -> bool {
77	    matches!(status, 429 | 500 | 502 | 503 | 504)
78	}
79	
80	#[cfg(test)]
81	mod tests {
82	    use super::*;
83	
84	    #[test]
85	    fn first_retry_uses_base_delay() {
86	        let config = RetryConfig { jitter_factor: 0.0, ..Default::default() };
87	        let delay = next_retry_delay(&config, 0, 0.0).unwrap();
88	        assert_eq!(delay, config.base_delay);
89	    }
90	
91	    #[test]
92	    fn second_retry_doubles() {
93	        let config = RetryConfig { jitter_factor: 0.0, ..Default::default() };
94	        let delay = next_retry_delay(&config, 1, 0.0).unwrap();
95	        assert_eq!(delay, config.base_delay * 2);
96	    }
97	
98	    #[test]
99	    fn delay_is_capped_at_max() {
100	        let config = RetryConfig {
101	            base_delay: Duration::from_secs(1),
102	            max_delay: Duration::from_secs(5),
103	            jitter_factor: 0.0,
104	            max_retries: 10,
105	        };
106	        let delay = next_retry_delay(&config, 5, 0.0).unwrap();
107	        assert_eq!(delay, Duration::from_secs(5));
108	    }
109	
110	    #[test]
111	    fn beyond_max_retries_returns_none() {
112	        let config = RetryConfig::default();
113	        assert!(next_retry_delay(&config, 3, 0.0).is_none());
114	    }
115	
116	    #[test]
117	    fn parse_retry_after_seconds() {
118	        assert_eq!(parse_retry_after("60"), Some(Duration::from_secs(60)));
119	        assert_eq!(parse_retry_after("  120  "), Some(Duration::from_secs(120)));
120	    }
121	
122	    #[test]
123	    fn parse_retry_after_date_returns_none() {
124	        assert!(parse_retry_after("Wed, 21 Oct 2015 07:28:00 GMT").is_none());
125	    }
126	
127	    #[test]
128	    fn retryable_status_codes() {
129	        assert!(is_retryable_status(429));
130	        assert!(is_retryable_status(503));
131	        assert!(!is_retryable_status(404));
132	        assert!(!is_retryable_status(400));
133	    }
134	
135	    #[test]
136	    fn non_retryable_status_codes() {
137	        assert!(!is_retryable_status(200));
138	        assert!(!is_retryable_status(201));
139	        assert!(!is_retryable_status(301));
140	        assert!(!is_retryable_status(401));
141	    }
142	
143	    #[test]
144	    fn jitter_increases_delay() {
145	        let config = RetryConfig {
146	            jitter_factor: 1.0,
147	            base_delay: Duration::from_millis(100),
148	            max_delay: Duration::from_secs(30),
149	            max_retries: 3,
150	        };
151	        let no_jitter = next_retry_delay(&RetryConfig { jitter_factor: 0.0, ..config.clone() }, 0, 0.0).unwrap();
152	        let with_jitter = next_retry_delay(&config, 0, 1.0).unwrap();
153	        assert!(with_jitter > no_jitter, "jitter seed 1.0 should produce longer delay");
154	    }
155	}
