5	/// Status of an individual pipeline step.
6	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
7	pub enum StepStatus {
8	    /// Step completed successfully.
9	    Completed,
10	    /// Step was skipped (dependency failed or step was configured best-effort).
11	    Skipped,
12	    /// Step failed.
13	    Failed,
14	    /// Step has not been attempted yet.
15	    Pending,
16	}
17	
18	impl StepStatus {
19	    /// The short label string used in rendered output.
20	    #[must_use]
21	    pub fn label(&self) -> &'static str {
22	        match self {
23	            Self::Completed => "completed",
24	            Self::Skipped => "skipped",
25	            Self::Failed => "failed",
26	            Self::Pending => "pending",
27	        }
28	    }
29	}
30	
31	/// A pipeline step definition (pure data — no execution logic in Plan 1).
32	#[derive(Debug, Clone)]
33	pub struct PipelineStep {
34	    /// Unique step identifier.
35	    pub id: String,
36	    /// Human-readable name.
37	    pub name: String,
38	    /// Current status.
39	    pub status: StepStatus,
40	}
41	
42	/// A pipeline run state (pure data, always compiled).
43	///
44	/// Renderable without the `pipeline` feature. The executor (Plan 2) produces
45	/// and updates this struct during a run.
46	#[derive(Debug, Clone, Default)]
47	pub struct Pipeline {
48	    /// Pipeline identifier (e.g. workflow name).
49	    pub id: String,
50	    /// All steps in declaration order.
51	    pub steps: Vec<PipelineStep>,
52	}
53	
54	impl Pipeline {
55	    /// Render the pipeline state as a TOON-style list for agent consumption.
56	    ///
57	    /// Format:
58	    /// ```text
59	    /// step[2]{id,name,status}:
60	    ///   fetch-data,Fetch Data,completed
61	    ///   upload,Upload,pending
62	    /// ```
63	    #[must_use]
64	    pub fn render(&self) -> String {
65	        let n = self.steps.len();
66	        let capacity = 30 + n * 40;
67	        let mut out = String::with_capacity(capacity);
68	
69	        out.push_str("step[");
70	        out.push_str(&n.to_string());
71	        out.push_str("]{id,name,status}:\n");
72	
73	        for step in &self.steps {
74	            out.push_str("  ");
75	            out.push_str(&step.id);
76	            out.push(',');
77	            // Escape name if it contains a comma
78	            if step.name.contains(',') {
79	                out.push('"');
80	                out.push_str(&step.name);
81	                out.push('"');
82	            } else {
83	                out.push_str(&step.name);
84	            }
85	            out.push(',');
86	            out.push_str(step.status.label());
87	            out.push('\n');
88	        }
89	
90	        out
91	    }
92	}
