  },
]

log('Starting adversarial review of michi: 5 dimensions reviewed in parallel, each finding independently verified by 3 lenses (reproduce, scope, severity).')

const results = await pipeline(
  DIMENSIONS,
  d => agent(d.prompt, { label: `find:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA }),
  (review, d) => {
    if (!review || !review.findings || review.findings.length === 0) {
      log(`${d.key}: 0 candidate findings`)
      return []
    }
