        const confirmed = votes.length > 0 && refutedCount < 2
        return { ...f, dimension: d.key, verdicts: votes, confirmed }
      })
    ))
  }
)

const all = results.filter(Boolean).flat().filter(Boolean)
const confirmed = all.filter(r => r.confirmed)
const severityRank = { critical: 0, high: 1, medium: 2, low: 3 }
confirmed.sort((a, b) => (severityRank[a.severity] ?? 4) - (severityRank[b.severity] ?? 4))

log(`${all.length} total candidate findings across ${DIMENSIONS.length} dimensions; ${confirmed.length} survived adversarial verification`)

return { confirmed, refuted: all.filter(r => !r.confirmed), totalCandidates: all.length }

