1	/// An opaque idempotency key derived from operation inputs.
2	///
3	/// Used to detect already-completed operations without re-executing them.
4	/// Callers derive the key from stable operation parameters, look it up in
5	/// their own store, and pass the lookup result — not the key itself — to
6	/// [`already_done`]: the key selects *which* record to check, and
7	/// `already_done` only needs to know what (if anything) that lookup found.
8	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
9	pub struct IdempotencyKey(pub String);
10	
11	impl IdempotencyKey {
12	    /// Create an idempotency key from any string-like value.
13	    pub fn new(s: impl Into<String>) -> Self {
14	        Self(s.into())
15	    }
16	
17	    /// The raw key string.
18	    pub fn as_str(&self) -> &str {
19	        &self.0
20	    }
21	}
22	
23	impl From<String> for IdempotencyKey {
24	    fn from(s: String) -> Self {
25	        Self(s)
26	    }
27	}
28	
29	impl From<&str> for IdempotencyKey {
30	    fn from(s: &str) -> Self {
31	        Self(s.into())
32	    }
33	}
34	
35	/// Result of an idempotency check.
36	#[derive(Debug, Clone, PartialEq)]
37	pub enum AlreadyDone {
38	    /// The operation completed in a previous call.
39	    Yes {
40	        /// The previously stored result.
41	        result: String,
42	    },
43	    /// The operation has not been seen before — proceed with execution.
44	    No,
45	}
46	
47	/// Check whether an operation has already completed.
48	///
49	/// Pass `stored` as `Some(result)` if a lookup in your own store by
50	/// [`IdempotencyKey`] found an entry; `None` if not. michi does not own any
51	/// persistence — the caller derives the key, retrieves and persists results
52	/// in their own store, and passes only the lookup outcome here.
53	///
54	/// Returns [`AlreadyDone::Yes`] when `stored` is `Some`, [`AlreadyDone::No`]
55	/// otherwise.
56	#[must_use]
57	pub fn already_done(stored: Option<String>) -> AlreadyDone {
58	    match stored {
59	        Some(result) => AlreadyDone::Yes { result },
60	        None => AlreadyDone::No,
61	    }
62	}
63	
64	/// Signals that an operation partially completed before a failure.
65	///
66	/// Use this when some steps of a multi-step operation succeeded — the agent
67	/// can resume from the checkpoint rather than retrying from scratch.
68	#[derive(Debug, Clone, PartialEq)]
69	pub struct PartialSuccess {
70	    /// Identifiers of steps that completed successfully.
71	    pub completed: Vec<String>,
72	    /// Identifiers of steps that were not attempted.
73	    pub remaining: Vec<String>,
74	    /// Human-readable reason for the partial completion.
75	    pub reason: String,
76	}
77	
78	impl PartialSuccess {
79	    /// Render this partial success as an agent-readable string.
80	    #[must_use]
81	    pub fn render(&self) -> String {
82	        format!("partial: {} completed, {} remaining — {}", self.completed.len(), self.remaining.len(), self.reason)
83	    }
84	}
85	
