8	use std::time::Duration;
9	
10	/// Configuration for automatic retry behaviour.
11	///
12	/// Callers implement the retry loop; michi provides the delay computation via
13	/// [`next_retry_delay`]. This keeps the crate sync and runtime-agnostic.
14	#[derive(Debug, Clone)]
15	pub struct RetryConfig {
16	    /// Maximum number of retry attempts (not counting the initial attempt).
17	    pub max_retries: u32,
18	    /// Base delay for exponential back-off.
19	    pub base_delay: Duration,
20	    /// Maximum delay cap — back-off never exceeds this.
21	    pub max_delay: Duration,
22	    /// Jitter factor in `[0.0, 1.0]`. `0.0` = no jitter, `1.0` = full jitter.
23	    pub jitter_factor: f64,
24	}
25	
26	// Manually implemented because the defaults are meaningful non-zero values
27	// that `#[derive(Default)]` cannot express (it would set all durations to zero).
28	impl Default for RetryConfig {
29	    fn default() -> Self {
30	        Self {
31	            max_retries: 3,
32	            base_delay: Duration::from_millis(500),
33	            max_delay: Duration::from_secs(30),
34	            jitter_factor: 0.2,
35	        }
36	    }
37	}
38	
39	/// Compute the delay before the next retry attempt.
40	///
41	/// Uses exponential back-off: `base_delay * 2^attempt`, with optional jitter
42	/// derived from `jitter_seed` (a value in `[0.0, 1.0]` supplied by the caller
43	/// — use a PRNG, not `rand` inside michi) added to the pre-cap delay. The
44	/// jittered total is then capped at `max_delay`, so the returned delay never
45	/// exceeds `max_delay` regardless of `jitter_factor`.
46	///
47	/// Returns `None` when `attempt >= config.max_retries`.
48	#[must_use]
49	// f64 arithmetic is used only to scale the jitter factor; jitter_seed and
50	// jitter_factor are documented as [0.0, 1.0], so the product is non-negative
51	// and the truncating cast back to u64 cannot lose sign or go negative.
52	#[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss, clippy::cast_sign_loss)]
53	pub fn next_retry_delay(config: &RetryConfig, attempt: u32, jitter_seed: f64) -> Option<Duration> {
54	    if attempt >= config.max_retries {
55	        return None;
56	    }
57	    let exp = 2u64.saturating_pow(attempt);
58	    let base_ms = u64::try_from(config.base_delay.as_millis()).unwrap_or(u64::MAX);
59	    let max_ms = u64::try_from(config.max_delay.as_millis()).unwrap_or(u64::MAX);
60	    let raw_ms = base_ms.saturating_mul(exp);
61	    let jitter_ms = (raw_ms as f64 * config.jitter_factor * jitter_seed) as u64;
62	    let jittered_ms = raw_ms.saturating_add(jitter_ms);
63	    let capped_ms = jittered_ms.min(max_ms);
64	    Some(Duration::from_millis(capped_ms))
65	}
66	
67	/// Parse the value of an HTTP `Retry-After` header as a delay in seconds.
68	///
69	/// Handles delay-seconds (integer) format. HTTP-date format is not parsed
70	/// (would require a date library dep) — returns `None` for dates.
71	/// Callers that need date parsing convert to seconds themselves.
72	#[must_use]
73	pub fn parse_retry_after(header_value: &str) -> Option<Duration> {
74	    header_value.trim().parse::<u64>().ok().map(Duration::from_secs)
75	}
76	
77	/// Return `true` if the HTTP status code is conventionally retryable.
78	///
79	/// Retryable status codes: 429 (rate limit), 500, 502, 503, 504.
80	#[must_use]
81	pub fn is_retryable_status(status: u16) -> bool {
82	    matches!(status, 429 | 500 | 502 | 503 | 504)
83	}
84	
