155	        };
156	        let no_jitter = next_retry_delay(&RetryConfig { jitter_factor: 0.0, ..config.clone() }, 0, 0.0).unwrap();
157	        let with_jitter = next_retry_delay(&config, 0, 1.0).unwrap();
