178	        let huge = Duration::from_secs(18_446_744_073_709_552);
179	        let config = RetryConfig { base_delay: huge, max_delay: huge, jitter_factor: 0.0, max_retries: 10 };
180	        let delay = next_retry_delay(&config, 0, 0.0).unwrap();
181	        assert!(delay.as_millis() > 1_000_000_000_000, "delay {delay:?} wrapped to a tiny value");
