55	/// A collection of status items with an overall health summary.
56	#[derive(Debug, Clone, PartialEq)]
57	pub struct StatusResponse {
58	    /// Aggregate health across all items.
59	    pub overall: Health,
60	    /// Individual component statuses.
61	    pub items: Vec<StatusItem>,
62	    /// Optional contextual hints for the agent.
63	    pub hints: Vec<Hint>,
64	}
65	
66	impl StatusResponse {
67	    /// Create a status response. `overall` is the caller-supplied aggregate — michi
68	    /// does not recompute it from `items` so the caller controls the roll-up logic.
69	    pub fn new(overall: Health, items: Vec<StatusItem>) -> Self {
70	        Self { overall, items, hints: Vec::new() }
71	    }
72	
73	    /// Attach contextual hints.
74	    #[must_use]
75	    pub fn with_hints(mut self, hints: Vec<Hint>) -> Self {
76	        self.hints = hints;
77	        self
78	    }
79	
80	    /// Render this status response as an agent-readable string.
81	    ///
82	    /// Format:
83	    /// ```text
84	    /// status: ok
85	    /// db: ok
86	    /// cache: degraded (high latency)
87	    /// queue: down
88	    /// help[1]:
89	    ///   check queue logs
90	    /// ```
91	    #[must_use]
92	    pub fn render(&self) -> String {
93	        let mut capacity = 16 + self.items.len() * 32;
94	        if !self.hints.is_empty() {
95	            capacity += 8 + self.hints.len() * 40;
96	        }
97	        let mut out = String::with_capacity(capacity);
98	        out.push_str("status: ");
99	        out.push_str(self.overall.label());
100	        out.push('\n');
101	        for item in &self.items {
102	            out.push_str(&item.name);
103	            out.push_str(": ");
104	            out.push_str(item.health.label());
105	            if let Some(detail) = &item.detail {
106	                out.push_str(" (");
107	                out.push_str(detail);
108	                out.push(')');
109	            }
110	            out.push('\n');
111	        }
112	        crate::hints::append_hints(&mut out, &self.hints);
113	        out
114	    }
115	}
