3	/// A single key-value pair for [`render_kv`].
4	#[derive(Debug, Clone, PartialEq)]
5	pub struct KvItem {
6	    /// The field name.
7	    pub key: String,
8	    /// The field value.
9	    pub value: KvValue,
10	}
11	
12	/// A value in a key-value item.
13	#[derive(Debug, Clone, PartialEq)]
14	pub enum KvValue {
15	    /// UTF-8 string value.
16	    Str(String),
17	    /// Signed integer.
18	    Int(i64),
19	    /// Floating-point number.
20	    Float(f64),
21	    /// Boolean renders as `true` or `false`.
22	    Bool(bool),
23	    /// Null renders as empty string after the colon.
24	    Null,
25	}
26	
27	/// Render a list of key-value pairs as a multi-line `key: value` block.
28	///
29	/// Preferred for single items and small metadata blocks (up to ~5 fields).
30	/// For lists of 5+ items, prefer [`crate::toon::render_toon`].
31	///
32	/// Returns an empty string when `items` is empty.
33	#[must_use]
34	pub fn render_kv(items: &[KvItem]) -> String {
35	    if items.is_empty() {
36	        return String::new();
37	    }
38	    let capacity = items.len() * 20;
39	    let mut out = String::with_capacity(capacity);
40	    for item in items {
41	        out.push_str(&item.key);
42	        out.push_str(": ");
43	        match &item.value {
44	            KvValue::Str(s) => out.push_str(s),
45	            KvValue::Int(n) => {
46	                let _ = write!(out, "{n}");
47	            }
48	            KvValue::Float(f) => {
49	                let _ = write!(out, "{f}");
50	            }
51	            KvValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
52	            KvValue::Null => {}
53	        }
54	        out.push('\n');
55	    }
56	    out
57	}
58	
