1	/// A structured recovery hint for an agent encountering an error.
2	///
3	/// Recovery hints give the agent concrete next steps when an operation fails,
4	/// rather than a bare error message.
5	#[derive(Debug, Clone, PartialEq)]
6	pub struct RecoveryHint {
7	    /// Short action label, e.g. `"retry"`, `"check_auth"`.
8	    pub action: String,
9	    /// Human-readable description of what this recovery achieves.
10	    pub description: String,
11	    /// An optional example invocation the agent can copy verbatim.
12	    pub example: Option<String>,
13	}
14	
15	impl RecoveryHint {
16	    /// Create a recovery hint with no example.
17	    pub fn new(action: impl Into<String>, description: impl Into<String>) -> Self {
18	        Self { action: action.into(), description: description.into(), example: None }
19	    }
20	
21	    /// Create a recovery hint with an example command or call.
22	    pub fn with_example(action: impl Into<String>, description: impl Into<String>, example: impl Into<String>) -> Self {
23	        Self { action: action.into(), description: description.into(), example: Some(example.into()) }
24	    }
25	}
26	
27	/// Render a list of recovery hints as an agent-readable block.
28	///
29	/// Format:
30	/// ```text
31	/// recovery[2]:
32	///   retry: call the endpoint again after 1s
33	///   check_auth: verify your API key is valid → get_token()
34	/// ```
35	///
36	/// Returns an empty string when `hints` is empty.
37	#[must_use]
38	pub fn render_recovery(hints: &[RecoveryHint]) -> String {
39	    if hints.is_empty() {
40	        return String::new();
41	    }
42	    let capacity = 16 + hints.len() * 60;
43	    let mut out = String::with_capacity(capacity);
44	    append_recovery(&mut out, hints);
45	    out
46	}
47	
48	/// Append a `recovery[N]:` block to an existing string in-place, without
49	/// allocating an intermediate buffer.
50	///
51	/// No-op when `hints` is empty.
52	pub fn append_recovery(out: &mut String, hints: &[RecoveryHint]) {
53	    if hints.is_empty() {
54	        return;
55	    }
56	    out.push_str("recovery[");
57	    out.push_str(&hints.len().to_string());
58	    out.push_str("]:\n");
59	    for hint in hints {
60	        out.push_str("  ");
61	        out.push_str(&hint.action);
62	        out.push_str(": ");
63	        out.push_str(&hint.description);
64	        if let Some(example) = &hint.example {
65	            out.push_str(" → ");
66	            out.push_str(example);
67	        }
68	        out.push('\n');
69	    }
70	}
