4	/// The serialisation format for `AgentResponse::render`.
5	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
6	pub enum OutputFormat {
7	    /// Plain-text TOON / kv / status format. Default.
8	    #[default]
9	    Text,
10	    /// Compact JSON object — field names match the builder setters.
11	    Json,
12	}
13	
14	/// Builder for composing a complete agent response from michi primitives.
15	///
16	/// An `AgentResponse` collects a primary content body, optional recovery hints,
17	/// optional contextual hints, and metadata, then renders the whole thing as a
18	/// single string via [`AgentResponse::render`].
19	///
20	/// # Examples
21	///
22	/// ```rust
23	/// use michi::response::{AgentResponse, OutputFormat};
24	/// use michi::hints::Hint;
25	///
26	/// let out = AgentResponse::new("issue[0]{}:\ntotalCount: 0\n")
27	///     .with_hint(Hint::new("Try a broader filter"))
28	///     .render(OutputFormat::Text);
29	/// assert!(out.contains("help[1]:"));
30	/// ```
31	#[derive(Debug, Clone)]
32	pub struct AgentResponse {
33	    /// Primary content body (TOON block, kv block, status block, etc.).
34	    pub body: String,
35	    /// Contextual hints appended after `body`.
36	    pub hints: Vec<Hint>,
37	    /// Structured recovery hints appended after `hints`.
38	    pub recovery: Vec<RecoveryHint>,
39	    /// Whether the response represents an error state.
40	    pub is_error: bool,
41	}
42	
43	impl AgentResponse {
44	    /// Create a new response with the given body. Hints and recovery are empty.
45	    pub fn new(body: impl Into<String>) -> Self {
46	        Self { body: body.into(), hints: Vec::new(), recovery: Vec::new(), is_error: false }
47	    }
48	
49	    /// Create a new response that represents an error state.
50	    pub fn error(body: impl Into<String>) -> Self {
51	        Self { body: body.into(), hints: Vec::new(), recovery: Vec::new(), is_error: true }
52	    }
53	
54	    /// Append a contextual hint.
55	    #[must_use]
56	    pub fn with_hint(mut self, hint: impl Into<Hint>) -> Self {
57	        self.hints.push(hint.into());
58	        self
59	    }
60	
61	    /// Replace all contextual hints.
62	    #[must_use]
63	    pub fn with_hints(mut self, hints: Vec<Hint>) -> Self {
64	        self.hints = hints;
65	        self
66	    }
67	
68	    /// Append a recovery hint.
69	    #[must_use]
70	    pub fn with_recovery(mut self, hint: RecoveryHint) -> Self {
71	        self.recovery.push(hint);
72	        self
73	    }
74	
75	    /// Replace all recovery hints.
76	    #[must_use]
77	    pub fn with_recoveries(mut self, hints: Vec<RecoveryHint>) -> Self {
78	        self.recovery = hints;
79	        self
80	    }
81	
82	    /// Mark this response as an error state.
83	    #[must_use]
84	    pub fn as_error(mut self) -> Self {
85	        self.is_error = true;
86	        self
87	    }
88	
89	    /// Render the response in the requested format.
90	    ///
91	    /// **Text format:** `body` + optional `help[N]:` block + optional `recovery[N]:` block.
92	    ///
93	    /// **Json format:** `{"body":"...","hints":[...],"recovery":[{"action":"...","description":"...","example":"..."}],"isError":false}`
94	    #[must_use]
95	    pub fn render(&self, format: OutputFormat) -> String {
96	        match format {
97	            OutputFormat::Text => self.render_text(),
98	            OutputFormat::Json => self.render_json(),
99	        }
100	    }
101	
102	    fn render_text(&self) -> String {
103	        let capacity = self.body.len() + self.hints.len() * 60 + self.recovery.len() * 80;
104	        let mut out = String::with_capacity(capacity);
105	        out.push_str(&self.body);
106	        crate::hints::append_hints(&mut out, &self.hints);
107	        crate::recovery::append_recovery(&mut out, &self.recovery);
108	        out
109	    }
110	
111	    fn render_json(&self) -> String {
112	        // Hand-built JSON — no serde dep in default features.
113	        let capacity = self.body.len()
114	            + self.hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>()
115	            + self.recovery.len() * 64
116	            + 64;
117	        let mut out = String::with_capacity(capacity);
118	        out.push_str("{\"body\":");
119	        json_string(&mut out, &self.body);
120	        out.push_str(",\"hints\":[");
121	        for (i, h) in self.hints.iter().enumerate() {
122	            if i > 0 {
123	                out.push(',');
124	            }
125	            json_string(&mut out, h.as_str());
126	        }
127	        out.push_str("],\"recovery\":[");
128	        for (i, r) in self.recovery.iter().enumerate() {
129	            if i > 0 {
130	                out.push(',');
131	            }
132	            out.push_str("{\"action\":");
133	            json_string(&mut out, &r.action);
134	            out.push_str(",\"description\":");
135	            json_string(&mut out, &r.description);
136	            if let Some(ex) = &r.example {
137	                out.push_str(",\"example\":");
138	                json_string(&mut out, ex);
139	            }
140	            out.push('}');
141	        }
142	        out.push_str("],\"isError\":");
143	        out.push_str(if self.is_error { "true" } else { "false" });
144	        out.push('}');
145	        out
146	    }
147	}
