149	/// Append a JSON-encoded string (with surrounding quotes and escape sequences)
150	/// to `out`. Escapes `"`, `\`, `\n`, `\r`, `\t`, and all other control characters
151	/// (U+0000–U+001F) as `\u00XX` per RFC 8259.
152	fn json_string(out: &mut String, s: &str) {
153	    out.push('"');
154	    for ch in s.chars() {
155	        match ch {
156	            '"' => out.push_str("\\\""),
157	            '\\' => out.push_str("\\\\"),
158	            '\n' => out.push_str("\\n"),
159	            '\r' => out.push_str("\\r"),
160	            '\t' => out.push_str("\\t"),
161	            other if u32::from(other) < 0x20 => {
162	                let code = u32::from(other);
163	                out.push_str("\\u00");
164	                out.push(hex_digit(code >> 4));
165	                out.push(hex_digit(code & 0xf));
166	            }
167	            other => out.push(other),
168	        }
169	    }
170	    out.push('"');
171	}
172	
173	/// Render a nibble (0–15) as a lowercase hex digit.
174	fn hex_digit(nibble: u32) -> char {
175	    char::from_digit(nibble, 16).unwrap_or('0')
176	}
