1	use std::fmt::Write as _;
2	
3	use super::escape::escape_value;
4	
5	/// A single cell value in a TOON row.
6	#[derive(Debug, Clone, PartialEq)]
7	pub enum Value {
8	    /// UTF-8 string. Escaped if it contains commas, quotes, carriage returns, or newlines.
9	    Str(String),
10	    /// Signed integer.
11	    Int(i64),
12	    /// Floating-point number.
13	    Float(f64),
14	    /// Boolean renders as `true` or `false`.
15	    Bool(bool),
16	    /// Null renders as empty string (delimiter still emitted by the caller).
17	    Null,
18	}
19	
20	/// Render a TOON document string from its parts.
21	///
22	/// Pre-allocates output capacity based on row count × estimated row width.
23	pub(crate) fn render(
24	    type_name: &str,
25	    fields: &[String],
26	    rows: &[Vec<Value>],
27	    total_count: Option<usize>,
28	    hints: &[String],
29	) -> String {
30	    let row_count = rows.len();
31	    let field_count = fields.len();
32	    let capacity = 60 + row_count * (field_count * 12 + 10) + hints.len() * 60;
33	    let mut out = String::with_capacity(capacity);
34	
35	    // type_name[count]{field,field,...}:
36	    out.push_str(type_name);
37	    out.push('[');
38	    out.push_str(&row_count.to_string());
39	    out.push_str("]{");
40	    for (i, field) in fields.iter().enumerate() {
41	        if i > 0 {
42	            out.push(',');
43	        }
44	        out.push_str(field);
45	    }
46	    out.push_str("}:\n");
47	
48	    // rows
49	    for row in rows {
50	        out.push_str("  ");
51	        for (i, val) in row.iter().enumerate() {
52	            if i > 0 {
53	                out.push(',');
54	            }
55	            match val {
56	                Value::Str(s) => out.push_str(&escape_value(s)),
57	                Value::Int(n) => {
58	                    let _ = write!(out, "{n}");
59	                }
60	                Value::Float(f) => {
61	                    let _ = write!(out, "{f}");
62	                }
63	                Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
64	                Value::Null => {}
65	            }
66	        }
67	        out.push('\n');
68	    }
69	
70	    // totalCount
71	    if let Some(total) = total_count {
72	        out.push_str("totalCount: ");
73	        out.push_str(&total.to_string());
74	        out.push('\n');
75	    }
76	
77	    // help[N]: hints
78	    if !hints.is_empty() {
79	        out.push_str("help[");
80	        out.push_str(&hints.len().to_string());
81	        out.push_str("]:\n");
82	        for hint in hints {
83	            out.push_str("  ");
84	            out.push_str(hint);
85	            out.push('\n');
86	        }
87	    }
88	
89	    out
90	}
