1	/// Escape a scalar value for TOON row output.
2	///
3	/// Values containing commas or double-quotes are wrapped in double-quotes
4	/// with internal double-quotes escaped as `\"`. Embedded newlines and
5	/// carriage returns are stripped, since TOON does not support multi-line
6	/// cell values. Empty values are returned as-is (the comma delimiter is
7	/// still emitted by the caller).
8	pub(crate) fn escape_value(v: &str) -> std::borrow::Cow<'_, str> {
9	    if v.is_empty() {
10	        return std::borrow::Cow::Borrowed(v);
11	    }
12	
13	    let mut needs_quote = false;
14	    let mut quote_count = 0usize;
15	    let mut stripped_count = 0usize;
16	    for ch in v.chars() {
17	        match ch {
18	            ',' => needs_quote = true,
19	            '"' => {
20	                needs_quote = true;
21	                quote_count += 1;
22	            }
23	            '\n' | '\r' => stripped_count += 1,
24	            _ => {}
25	        }
26	    }
27	
28	    if !needs_quote && stripped_count == 0 {
29	        return std::borrow::Cow::Borrowed(v);
30	    }
31	
32	    let capacity = v.len() - stripped_count + quote_count + if needs_quote { 2 } else { 0 };
33	    let mut out = String::with_capacity(capacity);
34	    if needs_quote {
35	        out.push('"');
36	    }
37	    for ch in v.chars() {
38	        match ch {
39	            '\n' | '\r' => {}
40	            '"' => {
41	                out.push('\\');
42	                out.push(ch);
43	            }
44	            _ => out.push(ch),
45	        }
46	    }
47	    if needs_quote {
48	        out.push('"');
49	    }
50	    std::borrow::Cow::Owned(out)
51	}
52	
