1	/// A contextual usage hint for an agent.
2	///
3	/// Hints are surfaced in `help[N]:` blocks at the end of TOON or kv responses.
4	/// They teach the agent what to call next.
5	#[derive(Debug, Clone, PartialEq)]
6	pub struct Hint(pub String);
7	
8	impl Hint {
9	    /// Create a hint from any string-like value.
10	    pub fn new(s: impl Into<String>) -> Self {
11	        Self(s.into())
12	    }
13	
14	    /// The raw hint string.
15	    pub fn as_str(&self) -> &str {
16	        &self.0
17	    }
18	}
19	
20	impl From<&str> for Hint {
21	    fn from(s: &str) -> Self {
22	        Self(s.into())
23	    }
24	}
25	
26	impl From<String> for Hint {
27	    fn from(s: String) -> Self {
28	        Self(s)
29	    }
30	}
31	
32	/// Render a `help[N]:` block from a slice of hints.
33	///
34	/// Returns an empty string when `hints` is empty.
35	#[must_use]
36	pub fn render_hints(hints: &[Hint]) -> String {
37	    if hints.is_empty() {
38	        return String::new();
39	    }
40	    let mut out = String::with_capacity(12 + hints.len() * 50);
41	    append_hints(&mut out, hints);
42	    out
43	}
44	
45	/// Append a `help[N]:` block to an existing string in-place, without
46	/// allocating an intermediate buffer.
47	///
48	/// No-op when `hints` is empty.
49	pub fn append_hints(out: &mut String, hints: &[Hint]) {
50	    if hints.is_empty() {
51	        return;
52	    }
53	    out.push_str("help[");
54	    out.push_str(&hints.len().to_string());
55	    out.push_str("]:\n");
56	    for hint in hints {
57	        out.push_str("  ");
58	        out.push_str(hint.as_str());
59	        out.push('\n');
60	    }
61	}
