1	/// Result of a truncation operation.
2	#[derive(Debug, Clone, PartialEq)]
3	pub struct Truncated {
4	    /// The truncated (or original) content string.
5	    pub content: String,
6	    /// Original byte length of the input.
7	    pub original_len: usize,
8	    /// Whether truncation actually occurred.
9	    pub was_truncated: bool,
10	}
11	
12	/// Truncate `content` to at most `max_chars` Unicode scalar values, appending
13	/// an agent-readable suffix when truncation occurs.
14	///
15	/// The suffix pattern is `" ({n} chars truncated — use {hint})"`. Uses char
16	/// boundaries — never splits a Unicode scalar.
17	///
18	/// Returns the original string unchanged when `content.chars().count() <= max_chars`.
19	#[must_use]
20	pub fn truncate(content: &str, max_chars: usize, hint: &str) -> Truncated {
21	    // Byte length is always >= char count, so if it already fits within
22	    // max_chars the char count does too — skip the full UTF-8 scan.
23	    if content.len() <= max_chars {
24	        return Truncated { content: content.to_string(), original_len: content.len(), was_truncated: false };
25	    }
26	
27	    let char_count = content.chars().count();
28	    if char_count <= max_chars {
29	        return Truncated { content: content.to_string(), original_len: content.len(), was_truncated: false };
30	    }
31	
32	    let suffix = format!(" ({char_count} chars truncated — use {hint})");
33	    let suffix_chars = suffix.chars().count();
34	    let keep_chars = max_chars.saturating_sub(suffix_chars);
35	
36	    let byte_end = content.char_indices().nth(keep_chars).map_or(content.len(), |(i, _)| i);
37	
38	    let mut result = String::with_capacity(byte_end + suffix.len());
39	    result.push_str(&content[..byte_end]);
40	    result.push_str(&suffix);
41	
42	    // Hard-cap to max_chars via char boundaries in case the suffix alone
43	    // exceeds max_chars (e.g. very small max_chars or long hint string).
44	    if result.chars().count() > max_chars {
45	        let cap_byte = result.char_indices().nth(max_chars).map_or(result.len(), |(i, _)| i);
46	        result.truncate(cap_byte);
47	    }
48	
49	    Truncated { content: result, original_len: content.len(), was_truncated: true }
50	}
51	
52	/// Truncate content for inline use (e.g. inside a TOON field).
53	///
54	/// Returns the final string directly.
55	#[must_use]
56	pub fn truncate_inline(content: &str, max_chars: usize, hint: &str) -> String {
57	    truncate(content, max_chars, hint).content
58	}
59	
