1	//! NAPI export surface for the `michi` npm package (`packages/michi-node`).
2	//!
3	//! `packages/michi-node/src/lib.rs` re-exports everything from this module
4	//! (`pub use michi::napi::*;`) rather than defining `#[napi]` items directly,
5	//! so the export logic can be unit-tested here alongside the rest of the
6	//! crate. `packages/michi-node` remains a separate Cargo crate only because
7	//! `crate-type = ["cdylib"]` cannot coexist with a regular `[lib]` in one
8	//! `Cargo.toml` — see `docs/superpowers/specs/2026-07-03-michi-design.md` §1.
9	//!
10	//! Every export uses `#[napi(catch_unwind)]` so a Rust panic cannot crash the
11	//! host Node.js process, and every export that accepts caller-controlled
12	//! collection sizes validates them against hard limits before doing any
13	//! work, since a single crafted call from untrusted JS is otherwise able to
14	//! force unbounded synchronous allocation on Node's single-threaded event
15	//! loop.
16	//!
17	//! This is the one module in the crate exempted from `#![deny(unsafe_code)]`
18	//! (src/lib.rs): `#[napi(catch_unwind)]` expands to macro-generated FFI glue
19	//! that needs `unsafe` to call into the N-API C ABI. No unsafe is hand-written
20	//! here — only the module-level allow below permits the macro expansion.
21	#![allow(unsafe_code)]
22	
23	use napi_derive::napi;
24	
25	/// Maximum row count accepted per [`render_toon`] call.
26	const MAX_ROWS: usize = 100_000;
27	/// Maximum field/column count accepted per header or row.
28	const MAX_FIELDS: usize = 1_000;
29	/// Maximum hint count accepted per call.
30	const MAX_HINTS: usize = 10_000;
31	
32	/// Value type for a TOON row cell (JavaScript-friendly).
33	///
34	/// Use the `type` field to discriminate: `"str"`, `"int"`, `"float"`, `"bool"`, `"null"`.
35	#[napi(object)]
36	pub struct JsToonValue {
37	    /// Discriminant: `"str"`, `"int"`, `"float"`, `"bool"`, or `"null"`.
38	    #[napi(js_name = "type")]
39	    pub r#type: String,
40	    /// The value when `type` is `"str"`.
41	    #[napi(js_name = "strVal")]
42	    pub str_val: Option<String>,
43	    /// The value when `type` is `"int"`.
44	    #[napi(js_name = "intVal")]
45	    pub int_val: Option<i32>,
46	    /// The value when `type` is `"float"`.
47	    #[napi(js_name = "floatVal")]
48	    pub float_val: Option<f64>,
49	    /// The value when `type` is `"bool"`.
50	    #[napi(js_name = "boolVal")]
51	    pub bool_val: Option<bool>,
52	}
53	
54	/// Options for rendering a TOON document (JavaScript-friendly).
55	#[napi(object)]
56	pub struct JsToonOptions {
57	    /// Snake_case type name, e.g. `"issue"`, `"component"`.
58	    #[napi(js_name = "typeName")]
59	    pub type_name: String,
60	    /// Ordered field names for the header.
61	    pub fields: Vec<String>,
62	    /// Rows, each a Vec of values parallel to `fields`. Capped at [`MAX_ROWS`]
63	    /// rows and [`MAX_FIELDS`] values per row.
64	    pub rows: Vec<Vec<JsToonValue>>,
65	    /// Total available count (may exceed `rows.len()` when paginated).
66	    #[napi(js_name = "totalCount")]
67	    pub total_count: Option<i32>,
68	    /// Agent-facing usage hints. Capped at [`MAX_HINTS`] entries.
69	    pub hints: Vec<String>,
70	}
71	
72	fn js_value_to_rust(v: JsToonValue) -> crate::toon::Value {
73	    match v.r#type.as_str() {
74	        "str" => crate::toon::Value::Str(v.str_val.unwrap_or_default()),
75	        "int" => crate::toon::Value::Int(i64::from(v.int_val.unwrap_or(0))),
76	        "float" => crate::toon::Value::Float(v.float_val.unwrap_or(0.0)),
77	        "bool" => crate::toon::Value::Bool(v.bool_val.unwrap_or(false)),
78	        _ => crate::toon::Value::Null,
79	    }
80	}
81	
82	/// Render a TOON list document from options.
83	///
84	/// # Errors
85	///
86	/// Returns an error if `rows`, `fields`, `hints`, or any row's value count
87	/// exceeds this module's hard size limits ([`MAX_ROWS`], [`MAX_FIELDS`],
88	/// [`MAX_HINTS`]) — an unbounded caller-supplied collection here would let a
89	/// single JS call force unbounded synchronous allocation on Node's event
90	/// loop, which `#[napi(catch_unwind)]` alone does not guard against.
91	#[napi(catch_unwind)]
92	pub fn render_toon(opts: JsToonOptions) -> napi::Result<String> {
93	    if opts.rows.len() > MAX_ROWS {
94	        return Err(napi::Error::from_reason(format!("rows length {} exceeds maximum of {MAX_ROWS}", opts.rows.len())));
95	    }
96	    if opts.fields.len() > MAX_FIELDS {
97	        return Err(napi::Error::from_reason(format!(
98	            "fields length {} exceeds maximum of {MAX_FIELDS}",
99	            opts.fields.len()
100	        )));
101	    }
102	    if opts.hints.len() > MAX_HINTS {
103	        return Err(napi::Error::from_reason(format!(
104	            "hints length {} exceeds maximum of {MAX_HINTS}",
105	            opts.hints.len()
106	        )));
107	    }
108	    for row in &opts.rows {
109	        if row.len() > MAX_FIELDS {
110	            return Err(napi::Error::from_reason(format!("row length {} exceeds maximum of {MAX_FIELDS}", row.len())));
111	        }
112	    }
113	
114	    // Casts are safe: total_count/max_chars are clamped non-negative first,
115	    // and usize is at least as wide as i32 on every platform this crate targets.
116	    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
117	    let rust_opts = crate::toon::ToonOptions {
118	        type_name: opts.type_name,
119	        fields: opts.fields,
120	        rows: opts.rows.into_iter().map(|row| row.into_iter().map(js_value_to_rust).collect()).collect(),
121	        total_count: opts.total_count.map(|n| n.max(0) as usize),
122	        hints: opts.hints,
123	    };
124	    Ok(crate::toon::render_toon(&rust_opts))
125	}
126	
127	/// Render a definitive empty state block: `type_name[0]{}:\ntotalCount: 0\n`.
128	#[napi(catch_unwind)]
129	#[allow(clippy::needless_pass_by_value)] // napi-derive requires owned String for JS string params
130	pub fn empty_state(type_name: String) -> String {
131	    crate::empty::empty_state(&type_name)
132	}
133	
134	/// Render a `help[N]:` hint block.
135	///
136	/// # Errors
137	///
138	/// Returns an error if `hints` exceeds [`MAX_HINTS`] entries.
139	#[napi(catch_unwind)]
140	pub fn render_hints(hints: Vec<String>) -> napi::Result<String> {
141	    if hints.len() > MAX_HINTS {
142	        return Err(napi::Error::from_reason(format!("hints length {} exceeds maximum of {MAX_HINTS}", hints.len())));
143	    }
144	    let h: Vec<crate::hints::Hint> = hints.into_iter().map(Into::into).collect();
145	    Ok(crate::hints::render_hints(&h))
146	}
147	
148	/// Truncate content to `max_chars` Unicode scalar values with an agent-readable suffix.
149	#[napi(catch_unwind)]
150	#[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)] // max_chars clamped non-negative first
151	#[allow(clippy::needless_pass_by_value)] // napi-derive requires owned String for JS string params
152	pub fn truncate(content: String, max_chars: i32, hint: String) -> String {
153	    crate::truncate::truncate_inline(&content, max_chars.max(0) as usize, &hint)
154	}
155	
156	#[cfg(test)]
157	mod tests {
158	    use super::*;
159	
160	    fn value(t: &str) -> JsToonValue {
161	        JsToonValue { r#type: t.to_string(), str_val: None, int_val: None, float_val: None, bool_val: None }
162	    }
163	
164	    #[test]
165	    fn render_toon_basic() {
166	        let opts = JsToonOptions {
167	            type_name: "issue".to_string(),
168	            fields: vec!["id".to_string()],
