192	            type_name: "issue".to_string(),
193	            fields: vec!["f".to_string(); MAX_FIELDS + 1],
194	            rows: vec![],
195	            total_count: None,
196	            hints: vec![],
197	        };
198	        assert!(render_toon(opts).is_err());
