216	            type_name: "issue".to_string(),
217	            fields: vec!["a".to_string()],
218	            rows: vec![(0..=MAX_FIELDS).map(|_| value("null")).collect()],
219	            total_count: None,
220	            hints: vec![],
221	        };
222	        assert!(render_toon(opts).is_err());
223	    }
224	
225	    #[test]
226	    fn empty_state_renders() {
227	        assert_eq!(empty_state("issue".to_string()), "issue[0]{}:\ntotalCount: 0\n");
228	    }
229	
230	    #[test]
231	    fn render_hints_basic() {
232	        let out = render_hints(vec!["do this".to_string()]).expect("valid input renders");
233	        assert!(out.contains("help[1]:"));
234	    }
